﻿using System;
using System.Linq.Expressions;
using Moq;
using Moq.Language;
using Moq.Language.Flow;
using Machine.Specifications;
using StructureMap.AutoMocking.Moq;

namespace Soon.TestingUtilities
{
    public abstract class Using_specs_for<T> where T : class
    {
        static MoqAutoMocker<T> autoMocker;

        Establish context = () =>
        {
            autoMocker = new MoqAutoMocker<T>();
        };

        protected static T ClassUnderTest => autoMocker.ClassUnderTest;
        protected static T Subject => autoMocker.ClassUnderTest;

        protected static Mock<TMock> GetTestDouble<TMock>() where TMock : class
        {
            return Moq.Mock.Get(autoMocker.Get<TMock>());
        }
        protected static Mock<TMock> Mock<TMock>() where TMock : class
        {
            return Moq.Mock.Get(autoMocker.Get<TMock>());
        }

        protected static TValue Any<TValue>()
        {
            return Moq.It.IsAny<TValue>();
        }

        protected static void Verify<TMock>(Expression<Action<TMock>> predicate) where TMock : class
        {
            Mock<TMock>().Verify(predicate);
        }

        protected static void Verify<TMock>(Expression<Action<TMock>> predicate, Times howOften) where TMock : class
        {
            Mock<TMock>().Verify(predicate, howOften);
        }

